function extractContent(result: InvokeResult): string {
  const content = result?.choices?.[0]?.message?.content;
  if (!content) return '';
  return typeof content === 'string' ? content : JSON.stringify(content);
}

function updateMetrics(
  result: GovernedGenerateResult,
  productKey: string,
  startTime: number,
): void {
  const latency = Date.now() - startTime;
  _metrics.avgLatencyMs = ((_metrics.avgLatencyMs * (_metrics.totalCalls - 1)) + latency) / _metrics.totalCalls;

  switch (result.decision) {
    case 'pass': _metrics.totalPassed++; break;
    case 'stabilize': _metrics.totalStabilized++; break;
    case 'block':
      _metrics.totalBlocked++;
      _metrics.byProduct[productKey].blocked++;
      break;
    case 'regenerate': _metrics.totalRegenerated++; break;
  }
}

/**
 * Reset metrics (for testing).
 */

